#include "../Source/PocketDSP.h"
#include <iostream>
#include <cstdlib>
#include <memory>
void test(bool b,const char* s){if(!b){std::cerr<<"FAIL "<<s<<'\n';std::exit(1);}}
double rmsFilter(double sr,double freq,float low,float high){pocket::SidechainFilter f;f.reset(sr);f.set(low,high);double sum=0;for(int n=0;n<(int)sr;++n){float x=(float)std::sin(6.28318530718*freq*n/sr);auto y=f.process({x,x});if(n>sr/2)sum+=y[0]*y[0];}return std::sqrt(sum/(sr/2));}
int main(){test(pocket::effectiveDepth(1)==1,"100 unchanged");test(std::abs(pocket::effectiveDepth(1.5f)-8)<1e-6,"150 = 8x");float previous=-1;for(int i=0;i<=1500;++i){float d=pocket::effectiveDepth(i/1000.f);test(d>=previous,"monotonic mapping");previous=d;}
 for(double sr:{44100.,48000.,96000.,192000.}){auto e=std::make_unique<pocket::Engine>();e->reset(sr,1.5f,1);e->configure(1.5f,0,1);for(int n=0;n<6000;++n){auto v=e->process({.8f,.4f},{.1f,.1f});if(n>pocket::N)test(std::abs(v.out[0]-.16f)<2e-6,"deep duck quiet key");}e->reset(sr,1.5f,1);e->configure(1.5f,0,1);for(int n=0;n<6000;++n){auto v=e->process({.8f,.4f},{.5f,.5f});if(n>pocket::N)test(v.out[0]==0,"no negative gain at extreme depth");}
  pocket::SidechainFilter f;f.reset(sr);for(int n=0;n<2000;++n){float x=(float)std::sin(n*.4);auto y=f.process({x,-x});test(y[0]==x&&y[1]==-x,"fullrange exact bypass");}test(rmsFilter(sr,80,3000,20000)<.002,"HP rejection");test(rmsFilter(sr,6000,3000,20000)>.6,"HP passes highs");test(rmsFilter(sr,6000,20,200)<.002,"LP rejection");test(rmsFilter(sr,80,20,200)>.6,"LP passes lows");for(int n=0;n<30000;++n){if(n%300==0)f.set(n%600?20:20000,n%900?20000:20);auto y=f.process({.8f,-.8f});test(std::isfinite(y[0])&&std::abs(y[0])<4,"automated filter stable");}}
 auto a=std::make_unique<pocket::Engine>(),b=std::make_unique<pocket::Engine>();a->reset(48000,1,0);b->reset(48000,1,0);a->configure(1,40,0);b->configure(1,40,0);double before=0,after=0;for(int n=0;n<24000;++n){float x=.6f*(float)std::sin(6.28318530718*93.75*n/48000);auto y=a->process({x,x},{x,x}),z=b->process({x,x},{-x,-x});test(std::abs(y.out[0]-z.out[0])<1e-6,"spectral key polarity invariance");if(n>8000){before+=x*x;after+=y.out[0]*y.out[0];}}test(after/before<.15&&after/before>.005,"broad spectral carve not arbitrary full erasure");
 a->reset(48000,1,0);a->configure(1,0,0);double sinLo=0,sinHi=0;for(int n=0;n<32768;++n){float lo=(float)std::sin(6.28318530718*93.75*n/48000),hi=(float)std::sin(6.28318530718*6000*n/48000);auto y=a->process({.4f*(lo+hi),.4f*(lo+hi)},{.5f*lo,.5f*lo});if(n>=16384){sinLo+=y.out[0]*lo;sinHi+=y.out[0]*hi;}}test(sinHi>sinLo*2,"spectrum selects bands instead of ducking everything");a->configure(1.5f,40,0,20,20000,true);for(int n=0;n<18000;++n){auto y=a->process({.3f,.15f},{1,1});if(n>15000)test(std::abs(y.out[0]-.3f)<1e-6,"bypass preserves latency compensated dry");}std::cout<<"PASS v0.4: 8x boost, no inversion, key filters, phase invariance, broad-band selectivity and bypass\n";}
